B=Path(__file__).resolve().parent;R=B.parents[3];sha=lambda b:hashlib.sha256(b).hexdigest();prep=json.loads((B/'qa_final_guard87/preparo.json').read_bytes());by={r['path']:r for r in prep['registros']};ctx=json.loads((B/'contextossnapshot.json').read_bytes());contexts={r['path']:r for r in ctx['registros']};technical=json.loads((B/'vinculos_tecnicos.json').read_bytes());css=json.loads((B/'diagnostico_glifossnapshot.json').read_bytes());held={}
