leg=[]
for r in ctx['registros']:
 if re.search(r'Congresso\s+Nacional.{0,90}(?:decretou|resolveu)',r['prefixo_antes_primeiro_artigo'],re.I|re.S):leg.append(r);hold(r['path'],'serie_legislativa_ambigua','Fórmula Congresso Nacional decretou e eu sanciono em índice DEC exige comprovação de série/identidade; não se cria alias ou nova norma por número semelhante.',r)
for r in css['retidos_para_revisao']:hold(r['path'],'glifo_normativo_Symbol','Fonte Symbol aplicada a U+F0BD no corpo normativo: Unicode igual não comprova equivalência do glifo. Retido sem substituir caractere por suposição.',r)
D=B/'retencoes_contextuais001';D.mkdir(exist_ok=False);records=list(held.values());assert len(records)==62;proofs=[]
